    kmaAngle: `**강사 양성 구조 있음** — "공개모집으로 선발된 이공계 전공 대학생들이 **관련 교사 프로그램을 이수한 후** 과학 수업과 멘토링을 진행". 14기 기준 9개 지역 × 3명 = **27명**, 아동 180명. 다만 **콘텐츠를 한국공학한림원이 쥐고 있어** 진입 여지가 좁음. E1 단독보다 **LS지주 사회공헌 라인**이 실질 타깃.`,
