    structure: `**정부 사업 참여형 — 자체 재단 운영이 아님.** 고용노동부·산업통상자원부 주관 **K-뉴딜 아카데미**에 기업 참여자로 들어가는 구조. **경북대학교·영남이공대학교와 컨소시엄**을 구성해 HI-CEED 아카데미를 운영 — 즉 **대학이 교육 수행기관**.`,
