    kmaAngle: `컨소시엄 구조라 대학(경북대·영남이공대)이 이미 자리를 잡음. 다만 **직무 커리큘럼 중 소프트스킬·리더십·안전 영역은 비어 있음** → 컨소시엄 보조 수행기관으로 제안 가능. K-뉴딜 아카데미는 정부 공모이므로 **KMA가 다른 기업과 컨소시엄을 짜서 직접 참여하는 경로**가 더 현실적.`,
