  "KB손해보험": {
    updated: `2026-09-04`,
    programs: [
      `KB금융공익재단 — KB스타 경제교실(초·중·고), KB스타 디지털 경제교실(메타버스), 금융권 진로교육, 알기 쉬운 경제이야기(발달장애인 맞춤), 온라인 KB Money SPACE. **누적 51,195회 교육 실시(2025.12.31 기준)**`,
      `KB손해보험 찾아가는 금융안심지원 — 2026.3 전주 시작, 전국 읍면사무소·복지관·노인회 협력. 금융사기 예방교육 + 웃음치료 결합형`,
      `KB손해보험 스타 히어로 챔프 — 순직·공상 소방공무원 자녀 50명, 대학생 멘토 1:1 주 2회 온라인 학습`,
    ],
    structure: `【KB금융 그룹 공통】 **⚠️ 단일 재단 전제가 틀림.** KB라이프생명이 별도로 **KB라이프생명사회공헌재단(2006.12)**을 보유하고, KB손해보험은 재단이 아니라 **자체 ESG추진팀 사회공헌파트**가 직접 운영. 그리고 결정적으로 **KB금융공익재단은 위탁형이 아니라 자체 강사풀 인하우스형**이다. 재단이 "경제금융교육 전문강사"를 직접 보유·모집해 현장에 파견하고, 자체 경제금융교육체험센터도 운영. **개인정보처리방침 위탁 항목이 ㈜프로엔솔루션(홈페이지 운영), 비즈톡㈜(알림톡) 두 곳뿐 — 교육 위탁사가 전무.** 외부 협력은 서울시복지재단(발달장애인 금융사기 예방), 한국중등교장협의회(KB라이프, 전국청소년자원봉사대회) 정도.`,
    contact: `**KB손해보험 ESG추진팀 사회공헌파트 02-6900-2353 / 2375** (실질 타깃) · KB금융공익재단 사무국 02-755-2243 · 재단 전문강사지원 https://www.kbfoundation.or.kr/my/supportProfessor.do (기관 위탁이 아니라 **개인 강사 등록** 창구) · KB라이프 구매입찰공시실 https://www.kblife.co.kr/customer-common/purchaseBiddingPublicNoticeOffice.do (내용 미확인)`,
    kmaAngle: `① **KB금융공익재단은 파트너보다 경쟁자에 가까움.** 자체 강사풀 + 자체 커리큘럼 + 자체 체험센터를 갖췄고 위탁 항목에 교육사가 0곳. 진입한다면 위탁이 아니라 개인 전문강사 등록 경로뿐. ② **실질 타깃은 KB손해보험 ESG추진팀(02-6900-2353).** 전국으로 확대 중인 찾아가는 프로그램을 자체 인력으로 굴리고 있어 운영 부담이 명확하고, "금융사기 예방교육 + 웃음치료" 결합형이라 외부 강사 조달 필요성이 구조적으로 존재.`,
    sources: [
      `https://www.kbfoundation.or.kr/`,
      `https://www.kbfoundation.or.kr/htmlView.do?pno=2299`,
      `http://www.kbinsure.co.kr/CU604010006.ec`,
      `https://insight.kbinsure.co.kr/260606_financial-education/`,
    ],
    unknown: [
      `KB라이프생명 사회공헌 상세 — 모바일 URL이 홈으로 리다이렉트`,
      `KB라이프생명사회공헌재단 독립 사이트 유무`,
      `KB손보 스타 히어로 챔프의 온라인 학습 플랫폼 사업자명`,
      `KB금융공익재단 사업 공모 여부`,
    ],
  },

