  "LS": {
    updated: `2026-09-04`,
    programs: [
      `LS드림사이언스클래스 — 2013~ 22기 진행 중. 초등 5·6학년 과학원리 수업 + 과학키트. **활동지역 9곳(부산·인천·울산·안양·동해·청주·천안·전주·구미), 지역별 3명 총 27명 이공계 대학생 멘토.** 2026년 활동 7.15~8.26, 접수 5.4~6.8`,
      `LS전선 잡스쿨링 — 강원대학교와 직접 계약, 2012~. 임직원(연구원·부장급) 직강, 대학 정규 교과 연계형`,
      `LS 드림센터(베트남 하노이 2023.5·하이퐁 2024.5) — 미취학 아동 돌봄, 가족 심리상담, 한국어 교실`,
      `LS드림스쿨(베트남 등 23개교 준공), LS MnM 사이언스 캠프, LS 러브 스토리(2025~)`,
    ],
    structure: `【LS 그룹 공통】 **⚠️ LS는 공익재단 자체가 없음.** 지주회사 ㈜LS가 그룹 캠페인을 총괄하고 대표 교육사업은 초록우산과 공동 수행. **초록우산이 실질 사무국**임이 확정됨 — LS드림사이언스클래스 대학생 멘토 모집 공고를 초록우산이 자기 사이트에 게시하고, 각 대학이 "[초록우산] LS드림사이언스클래스 N기 멘토 모집"으로 재공지. LS전선 잡스쿨링은 강원대와 직접 계약. 대학생 해외봉사단은 임직원 + 대학생 + "NGO 전문가" 구성(NGO명 미표기).`,
    contact: `**초록우산 경유가 사실상 유일한 접점** https://www.chorogusan.or.kr/ · LS그룹 사회공헌 https://www.lsholdings.com/ko/csv/science · 운영사무국 02-799-0486 · 공개 입찰·공모 창구는 확인 못 함`,
    kmaAngle: `① **초록우산이 LS 교육 사회공헌의 실질 사무국** — 드림사이언스클래스 멘토 선발·운영 전체를 집행. **9개 지역 27명 멘토를 매년 모집·교육하는 구조라 멘토 사전연수(강사 양성) 파트가 명확한 외주 대상.** ② LS전선 잡스쿨링이 강원대 1개교 단일 협약을 13년째 유지 — 임직원 직강 방식이라 교수설계·평가 지원 여지. ③ 재단이 없으므로 접근은 계열사 개별 접촉 또는 초록우산 경유 두 갈래뿐.`,
    sources: [
      `https://www.lscns.co.kr/kr/intro/social_contribution.asp`,
      `https://www.etoday.co.kr/news/view/2587460`,
      `https://www.chorogusan.or.kr/news/noticeView.do?bdId=20043061&bmId=10000023`,
    ],
    unknown: [
      `㈜LS 지주 사회공헌 페이지 본문 — 빈 페이지로 렌더링`,
      `LS일렉트릭 자체 교육 사회공헌 확인 못 함 (확인된 것은 장애인 합창단 "그린 보이스"뿐)`,
      `LS전선·LS일렉트릭 개인정보처리방침 위탁 항목`,
      `대학생 해외봉사단의 "NGO 전문가" 소속 기관명`,
    ],
  },

