  "S-Oil": {
    updated: `2026-09-04`,
    programs: [
      `S-OIL 친환경 사회적기업 성장지원사업 — **열매나눔재단** 수행, 2022~ 3년 이상. 별도 사이트 s-oilgreenchallenger.kr`,
      `어린이 천연기념물 교실·생태캠프, 대학생 천연기념물 지킴이단 — 문화재청 협약 2008~`,
      `과학문화재단 — 순수과학 장학·학술연구논문 지원·한-아랍 학술문화교류(청년교류 2024~2025)`,
      `취약계층 학생 초청 과학아카데미(2025.5), 소방·해경 순직자 유자녀 학자금`,
    ],
    structure: `자체 운영 + 사업별 파트너십. **2개 별도 재단 보유**(과학문화재단, 울산복지재단).`,
    contact: `**에쓰-오일 과학문화재단 사무국 최칠성 차장 02-3772-5505 / star1016@s-oil.com** (서울 마포구 백범로 192 본사 9층) · 공모 게시판 없음(공지사항은 활동소식·공시자료만) · 울산공장은 연초 지역 복지기관 대상 봉사프로그램 공모 별도 시행(온라인 창구 미확인)`,
    kmaAngle: `**우선순위 낮음.** 재단 목적사업이 순수과학 장학·연구지원·한중동 교류로 정관에 한정돼 일반 기업교육 위탁은 범위 밖. 사무국 직통 연락처가 유일한 자산. 본사 사회공헌 담당은 별도 확인 필요.`,
    sources: [
      `https://www.s-oil.com/relation/Contribution02.aspx`,
      `https://www.s-oil.com/relation/Contribution04_NoticeList.aspx`,
    ],
    unknown: [
      `본사(재단 아님) 사회공헌 담당 부서·연락처`,
    ],
  },

  "SK": {
    updated: `2026-09-02`,
    programs: [
      `SK 뉴스쿨 — 청년 무료 직업교육 5개 학과(조리·카페베이커리·MD·정보보안·자동차판금도장). 2008~ 누적 884명, 2025년 취업률 99%`,
      `Sunny Scholar / On-Site / Global — 청년 사회문제해결 인재양성. On-Site 2기 2026.07 시작`,
      `행복얼라이언스 스쿨 — 2022~. 2025년 7개 지역 200여명, 누적 29개 지역 890여명`,
      `희망메이커 School (SK디스커버리 계열) — 전국 12개 사회복지관, 2025년 약 300명`,
      `SK실트론 반도체스쿨 — 2023~. 2026년 10개교 2,005명, 사업비 9천만원`,
      `노노스쿨(신중년), 씈싹씈싹 스쿨(SK바이오사이언스 감염병 예방교육)`,
      `행복한학교 (~2018 종료, 2019 행복나래 이관) / KAIST 사회적기업가 MBA (~2018 종료, 이관) / SK 프로보노 (~2018 종료, 이관) / 사회혁신교육자네트워크 ENSI (2017~2018 종료)`,
    ],
    structure: `【SK 그룹 공통】 **⚠️ 행복나눔재단이 계열사 공통 창구라는 전제는 틀림.** 지목된 7개 계열사 중 행복나눔재단을 창구로 쓰는 곳이 한 곳도 확인되지 않음. 최소 4개 독립 법인이 나눠 운영: ① **행복나눔재단**(SK㈜, 2005~) — 현재 7개 사업 전부 자체 개발·자체 운영. 2019년 대외 사회공헌 사업 대부분을 행복나래로 이관. ② **행복나래㈜** — 실질적 그룹 CSR 실행 허브. 행복얼라이언스 사무국·SK프로보노·SOVAC 운영. ③ **행복에프앤씨재단** — SK 뉴스쿨·노노스쿨 실제 운영 법인. ④ **SK디스커버리 지주 계열**(SK케미칼·SK가스·SK바이오사이언스) — SK㈜가 아니라 최창원 회장 산하 별도 그룹, 자체 브랜드 "희망메이커". 교육 위탁 사례: **행복한학교재단**(행복얼라이언스 스쿨 교육 운영·모니터링 수탁), **㈜마크앤컴퍼니**(2026 소셜벤처 육성 프로그램 운영 — 행복나래 위탁표에 명시), ㈜상상우리(SE컨설턴트 관리). **※ SK스페셜티는 2025년 3월 한앤컴퍼니가 지분 85%(약 2.6조원) 인수 완료로 SK 계열 아님.**`,
    contact: `**행복나래㈜** https://www.happynarae.com (실질 창구) · 행복얼라이언스 사무국 https://www.happyalliance.org/ · SK뉴스쿨 sknewschool@skhappiness.org · 행복나눔재단 02-333-3963 · CSES info@cses.re.kr 02-6275-0410 · SK실트론 반도체스쿨은 **구미시·구미상공회의소**가 주관`,
    kmaAngle: `① **행복나눔재단이 아니라 행복나래㈜에 제안할 것.** 2019년 행복한학교·KAIST MBA·프로보노를 모두 이관받았고, 개인정보처리방침 위탁표에 마크앤컴퍼니에게 "2026년 소셜벤처 육성 프로그램 운영"을 실제 외주 준 기록이 있음 — **교육·육성 운영을 외부에 위탁하는 관행이 문서로 확인된 유일한 SK 조직.** ② **행복얼라이언스 스쿨 교육 운영 수탁 자리** — 현재 행복한학교재단 단독. 2025년 7개 지역·18개 멤버기업으로 확장 중이라 운영 역량 수요 증가. ③ **SK실트론 반도체스쿨 강사 양성** — 구미시가 "지역 전문 강사 양성에 힘을 쏟고 있다"고 명시. 현재 자체 양성이라 강사 연수·교수법 표준화가 KMA 영역. 접촉선은 SK실트론이 아니라 구미시·구미상공회의소. ④ **진입하지 말 것: 행복나눔재단 본체.** 현재 7개 사업 전부 자체 실행 노선이고 위탁표에 교육 벤더가 0곳.`,
    sources: [
      `https://skhappiness.org/`,
      `https://archive.skhappiness.org/`,
      `https://www.happynarae.com/happy2/index.jsp`,
      `https://www.happyalliance.org/`,
      `https://www.sknewschool.com/web/notice/all`,
      `https://www.happyfnc.org/web/education`,
      `http://www.guminews.co.kr/bbs/board.php?bo_table=news&wr_id=112225`,
    ],
    unknown: [
      `sk.co.kr 전체 접근 불가 — 그룹 통합 사회공헌 페이지 미확인`,
      `각 프로그램의 예산 규모·계약 방식(수의계약/공모 여부)`,
      `SK E&S 착한에너지학교의 현재 운영 여부·수행기관 — 2024년 SK이노베이션 합병 후 종료 가능성 있으나 미확인`,
      `SK렌터카: 교육 프로그램 자체가 확인되지 않음(사회공헌은 차량지원 중심)`,
      `행복나눔재단 위탁표에는 교육 벤더 0곳 — 삼성에서 통한 방법이 SK 재단에는 무효`,
    ],
  },

