    contact: `**행복나래㈜** https://www.happynarae.com (실질 창구) · 행복얼라이언스 사무국 https://www.happyalliance.org/ · SK뉴스쿨 sknewschool@skhappiness.org · 행복나눔재단 02-333-3963 · CSES info@cses.re.kr 02-6275-0410 · SK실트론 반도체스쿨은 **구미시·구미상공회의소**가 주관`,
