    structure: `★ **D등급이 명백한 오분류.** 은행 자체 운영 + 재단 병행 이원 구조로, 사회공헌 전용 사이트(happybnk.co.kr) + **BNK금융그룹 희망나눔재단**(bnknanum.com) + 금융교육 전용 앱/신청사이트 + 금융역사관 + 기장연수원 캠프 + 7개 분야 재능기부봉사대 + **외부 공모사업**까지 완비. 협력: 부산지방기상청(기후변화과학+금융교육 공동 프로그램 개발, 2025.2.25), 금융감독원 부산울산지원, 부산사회서비스원(노인일자리 참여자 금융교육), 초록우산(공공형 키즈카페), 부산광역시교육청, 남부교육지원청.`,
