    kmaAngle: `★ **D등급 129곳 중 1순위.** ① **재능기부봉사대**(2015.5 창단) — **금융교육·어학·등산·미술·구연동화·정보통신(IT)·음악 7개 분야 직원 강사팀**이 월 1회 이상 아동양육시설·지역아동센터·장애인시설·다문화가정·초중고에 재능기부 신청을 받아 파견. **그 직원들을 누가 강사로 교육·양성하는지가 페이지에 전혀 없음** — 지금까지 확인된 15개 기업 공통 공백과 정확히 같은 자리. ② 희망나눔재단 공모사업 응모 ③ 금융클래스 교안·콘텐츠 개발 위탁.`,
