  "씨제이올리브네트웍스": {
    updated: `2026-09-07`,
    programs: [
      `★ **꿈키움 문화다양성 교실**(2023~) — 2026년 전국 지역아동센터 600곳·**교사 600명** 모집(~5/20), 아동 약 9,000명. 누적 1,200개 센터·교사 1,200명·아동 2만명`,
      `CJ도너스캠프 아카데미(2017~ 10년차) — 취업취약청년 18~34세. 전액 무료 + 월 50만원 교육지원금 + 지방생 거주비 50만원. **2026 하반기 60명**(F&B 서비스 10/베이커리 서비스 16/H&B 서비스 16/베이커리 제빵 18). 누적 수료 1,000명, **취업률 85% 초과**. 직업계고 3학년 100명 과정 별도`,
      `CJ올리브영 **My First ME:RACLE** — 자립준비청년. 1기 50명(2025.10~), 메이크업 국가자격증 120시간 교육비 전액 + 실습도구 + 생활장학금, 5~6개월. 1기 수료식 2026.5.21, 우수 10명 LA 로레알 본사 견학. **2기 2026 하반기 출범 예정**`,
      `꿈키움 장학 — 지역아동센터·아동복지시설 예체능·기술·학업 우수 청소년`,
      `CJ올리브네트웍스 초등생 AI·자율주행자동차 실습(2024년 119명, 2025 상반기 60명)`,
      `핑크박스 나눔 캠페인 (2016~**2025 종료**) → ME:RACLE BOX로 개편·전국 확대`,
    ],
    structure: `【CJ 그룹 공통】 **⚠️ CJ나눔재단이 계열사 공통 창구라는 전제는 부분적으로 틀림.** **CJ올리브영은 재단을 거치지 않고 자체 지속가능경영팀이 ME:RACLE 브랜드를 직접 운영**하고, CJ올리브네트웍스도 자체 임직원 봉사단 방식. **꿈키움 문화다양성 교실은 비용·역할이 분리돼 있음** — 커리큘럼과 사업비 5억원은 **금융산업공익재단**이, 운영과 사업비 2억원은 CJ도너스캠프가 부담. 교구(워크북·보드게임·카드세트)도 금융산업공익재단 개발. 그 외 교육부·대한상공회의소(직업계고 채용연계형 직무교육 4년 연속 선정), 티머니복지재단, 효창종합사회복지관(올리브네트웍스). 콘텐츠 참여로 최태성·이원복 교수.`,
    contact: `**CJ도너스캠프 www.donorscamp.org** — 참여기관(수요처) 공모. 지역아동센터·그룹홈·아동양육시설·중고교·청소년수련관이 회원가입 후 제안서 제출. 꿈키움 문화다양성 교실은 매년 **~5월 20일 마감** · CJ올리브영 미라클 교육생 모집은 corp.oliveyoung.com 게시 · CJ올리브네트웍스 02-6252-0291 / cs_ons@cj.net · **※ 수행기관(교육 공급자) 대상 입찰 게시판은 확인 못 함**`,
    kmaAngle: `★ **꿈키움 문화다양성 교실이 지금까지 본 강사 양성 사례 중 규모·문서화가 가장 명확함.** 재단 문구 원문: *"지역아동센터 교사를 강사로 양성하고, 양성된 교사가 소속 센터 아동을 대상으로 직접 수업을 진행"* — 연 600명 규모, 누적 1,200명, **교사 교수효능감 측정·리포트 제공까지 포함.** 커리큘럼은 금융산업공익재단이 개발하고 운영은 CJ도너스캠프이므로, **교사 연수 설계·운영·효과성 측정**이 KMA 역량과 직접 맞음. ② **CJ도너스캠프 아카데미 서비스 매니저 과정** — 2026 하반기부터 "글로벌 고객 응대", "고객 특성별 셀링", "글로벌 트렌드 & K뷰티 시장 이해", 영어 교육을 신규·강화. **서비스 응대 교육은 KMA 전통 영역.** ③ **ME:RACLE 2기(2026 하반기)** — "전문 기관과 연계한 교육 활동"을 매 기수 조달하는데 기관명이 미공개 = 경쟁 가능 지점.`,
    sources: [
      `https://www.fintechtimes.co.kr/news/article.html?no=55452`,
      `https://cjnews.cj.net/ai가-못-읽는-고객의-마음-cj도너스캠프-2026-cj도너/`,
      `https://cjnews.cj.net/cj올리브영-사회공헌-브랜드-미라클-출범하고-자/`,
      `https://cjnews.cj.net/나로부터-시작된-기적-120시간의-도움닫기-올리브영/`,
    ],
    unknown: [
      `CJ도너스캠프 아카데미의 실제 교육 위탁사 — 교육장·강사 조달 방식`,
      `ME:RACLE "전문 기관"의 실명`,
      `CJ도너스캠프 담당자 연락처`,
      `donorscamp.org가 JS 렌더링이라 본문 직접 확인 실패`,
    ],
  },

