    structure: `★ **기부금 245.5억으로 484곳 중 최대이지만 D등급이 실질에 가깝다.** 기부금 대부분이 서울시 취약계층 대상 **현물(제품) 기부**로 확인됨 — 13년 누적 483억, 2026년 시점 누적 566억. **금액은 최대지만 교육사업 밀도는 낮음.** 자체 운영, 별도 재단 없음. 협력: 밀알복지재단(나눔스토어 기빙플러스), 마포구청 3자 MOU(2025.4.28), 아름다운가게. ※ 공식 사이트가 aekyungind.co.kr이 아니라 **aekyung.co.kr**.`,
    contact: `**사회공헌 전용 공모·제안 창구 없음.** 확인된 창구는 고객만족팀 "아이디어제안"(aekyung.co.kr/cs_idea)과 "제보하기"(윤리) — 둘 다 사회공헌용 아님. 사회공헌 담당(마포 본사) 직접 접촉 필요`,
    kmaAngle: `**기부금 규모에 현혹되지 말 것 — 현물기부 중심이라 교육 위탁 구조가 거의 없다.** 유일한 빈틈은 "재능인재 장학생 지원", "이주배경청소년장학금"이 **프로그램화되어 있지 않다는 점** — **장학금에 교육 프로그램을 붙이는 설계 제안**이 각도. 창구가 없어 직접 접촉만 가능.`,
