    structure: `【에스케이스페셜티 고유】 ⚠️ 2025년 3월 한앤컴퍼니가 지분 85%(약 2.6조원) 인수 완료 — **더 이상 SK 계열이 아님.** SK㈜ 15% 잔여 보유. 제안 대상 재검토 필요.

【SK 그룹 공통】 **⚠️ 행복나눔재단이 계열사 공통 창구라는 전제는 틀림.** 지목된 7개 계열사 중 행복나눔재단을 창구로 쓰는 곳이 한 곳도 확인되지 않음. 최소 4개 독립 법인이 나눠 운영: ① **행복나눔재단**(SK㈜, 2005~) — 현재 7개 사업 전부 자체 개발·자체 운영. 2019년 대외 사회공헌 사업 대부분을 행복나래로 이관. ② **행복나래㈜** — 실질적 그룹 CSR 실행 허브. 행복얼라이언스 사무국·SK프로보노·SOVAC 운영. ③ **행복에프앤씨재단** — SK 뉴스쿨·노노스쿨 실제 운영 법인. ④ **SK디스커버리 지주 계열**(SK케미칼·SK가스·SK바이오사이언스) — SK㈜가 아니라 최창원 회장 산하 별도 그룹, 자체 브랜드 "희망메이커". 교육 위탁 사례: **행복한학교재단**(행복얼라이언스 스쿨 교육 운영·모니터링 수탁), **㈜마크앤컴퍼니**(2026 소셜벤처 육성 프로그램 운영 — 행복나래 위탁표에 명시), ㈜상상우리(SE컨설턴트 관리). **※ SK스페셜티는 2025년 3월 한앤컴퍼니가 지분 85%(약 2.6조원) 인수 완료로 SK 계열 아님.**`,
    contact: `**행복나래㈜** https://www.happynarae.com (실질 창구) · 행복얼라이언스 사무국 https://www.happyalliance.org/ · SK뉴스쿨 sknewschool@skhappiness.org · 행복나눔재단 02-333-3963 · CSES info@cses.re.kr 02-6275-0410 · SK실트론 반도체스쿨은 **구미시·구미상공회의소**가 주관`,
    kmaAngle: `① **행복나눔재단이 아니라 행복나래㈜에 제안할 것.** 2019년 행복한학교·KAIST MBA·프로보노를 모두 이관받았고, 개인정보처리방침 위탁표에 마크앤컴퍼니에게 "2026년 소셜벤처 육성 프로그램 운영"을 실제 외주 준 기록이 있음 — **교육·육성 운영을 외부에 위탁하는 관행이 문서로 확인된 유일한 SK 조직.** ② **행복얼라이언스 스쿨 교육 운영 수탁 자리** — 현재 행복한학교재단 단독. 2025년 7개 지역·18개 멤버기업으로 확장 중이라 운영 역량 수요 증가. ③ **SK실트론 반도체스쿨 강사 양성** — 구미시가 "지역 전문 강사 양성에 힘을 쏟고 있다"고 명시. 현재 자체 양성이라 강사 연수·교수법 표준화가 KMA 영역. 접촉선은 SK실트론이 아니라 구미시·구미상공회의소. ④ **진입하지 말 것: 행복나눔재단 본체.** 현재 7개 사업 전부 자체 실행 노선이고 위탁표에 교육 벤더가 0곳.`,
