  "우리금융캐피탈": {
    updated: `2026-09-07`,
    programs: [
      `우리러너(고2~3) / 우리미래서울러너(고1) 3기 — 총 250명(2026.4.12 출범). **연 200만원 학습비를 우리카드 제휴 카드 바우처로 지급.** 2박3일 여름캠프, 3주 이내 겨울 윈터스쿨, 연 2회 1:1 입시 컨설팅. 고3은 연 3회 맞춤 로드맵 + 수시전략·수능대비 특강 + 합격 시 100만원 입학장학금`,
      `WOORI Chance 금융교육 — 자립준비청년 만18~29세, 2026.6 기준 7기`,
      `우리 어르신 IT 행복 배움교실 — 반기별 운영, 2026 상반기 수강 안내 게시`,
      `중학생 진로/교육, 만35세 이하 멘토링("우리사이")`,
    ],
    structure: `【우리금융 그룹 공통】 **⚠️ 그룹 내 재단이 셋 — "공통 창구 하나"라는 전제는 틀림.** 우리금융미래재단(계열사 공동출연) / 우리다문화장학재단 / 우리미소금융재단. **우리러너·우리미래서울러너의 운영 주관은 사회복지법인 아이들과미래재단**(이사장 이훈규). 그 밖에 서울시 "서울런" 연계, 예일대 YYGS 서머캠프, 수능 강사 김민정·주혜연 참여, 기숙학원 연계 윈터스쿨. 개인정보처리방침 위탁사는 ㈜가비아씨엔에스(사이트 유지보수) 1곳뿐 — 교육 위탁사 단서 없음.`,
    contact: `★ **업체 대상 공개 입찰 게시판 확인됨** https://woorifuturefoundation.or.kr/news/boardList?category=notice — 실물 2건: "온라인 콘텐츠 제작 대행사 입찰 공고"(2025.11.20), "발달장애 미술가 작품 전시회 기획·운영 업체 입찰공고"(2025.11.10). **교육 용역 입찰 사례는 아직 없으나 재단이 외부 업체를 공개입찰로 조달하는 관행이 확립돼 있음.** 게시가 11월에 몰려 있어 연말 발주 패턴으로 추정됨(추정). 재단 사무국 **02-2125-2145 / woorifufo@woorifuture.or.kr** · 강소영 과장 02-2125-2196 / sykang@woorifuture.or.kr · 석진형 차장 02-2125-2293`,
    kmaAngle: `① **재단 공지 입찰 게시판 상시 모니터링 + 사무국(02-2125-2145)에 교육 용역 제안** — 근거 있는 유일한 경로. ② 우리러너는 **아이들과미래재단이 이미 운영사무국을 쥐고 있어 진입 난도가 높음.** 다만 아이들과미래재단은 **연 80여 개 파트너 기업·60여 개 CSR 프로그램을 운영하는 중간지원조직**이므로, 우리금융이 아니라 **아이들과미래재단 쪽에 콘텐츠 공급자로 접근하는 경로**가 더 현실적. (같은 재단이 유니클로 "천천히 함께", HD현대 파이썬 교육도 수행 — 반복 등장하는 핵심 중간조직)`,
    sources: [
      `https://woorifuturefoundation.or.kr/`,
      `https://woorifuturefoundation.or.kr/business/future`,
      `https://woorifuturefoundation.or.kr/news/boardList?category=notice`,
      `https://press.expressnews.co.kr/newsRead.php?no=1032226`,
    ],
    unknown: [
      `우리카드 문화/교육 사회공헌 세부 — 탭 콘텐츠 렌더링 실패, "다문화 금융교육" 항목명만 확인`,
      `우리벤처파트너스 교육사업 — 명륜보육원 현물 기증만 검색됨(교육 아님)`,
      `WOORI Chance 금융교육 수행기관`,
    ],
  },

