    structure: `자체 + 외부 재단 후원 혼합. 다만 **사회공헌 성격의 교육사업은 확인 못 함.**`,
    contact: `나눔 복사 캠페인은 홈페이지·SNS로 참여기업 공모(2023년 기준 5/3~5/16) — 단 교육이 아닌 사무기 지원 · 공지사항 https://m.kr.canon/company/notice/list`,
    kmaAngle: `**사회공헌 교육 트랙은 사실상 없음.** 캐논아카데미 기업 출강 사업의 B2B 유통 파트너로서의 여지만 존재. 우선순위 낮음.`,
