    contact: `포스코1%나눔재단 nanum@poscofoundation.org · 02-3457-1002 · 의견보내기 폼 "1% 채우는 톡톡"에 **'제안합니다' 분류가 있음 — 공식 입찰 창구가 없는 대신 유일한 제도적 제안 경로** · 공지 https://www.poscofoundation.org/front/word/notice/list.do · 포스코청암재단 02-562-0398 / 054-279-0075 · **계열사 직접 접촉이 재단보다 효과적**`,
