    kmaAngle: `★ **B등급 중 두 번째로 유망.** "사내강사 교육기부 프로그램"이 홈페이지 본문에 명시돼 있고, **임직원을 강사로 양성해 외부에 파견하는 구조는 KMA 주력 상품(사내강사 양성·교수법)과 정확히 일치.** 다만 규모·대상·양성 주체가 홈페이지에 없어 통화로 확인해야 함. 익산 본사 직접 콜이 현실적.`,
