    structure: `**자체 운영.** 사내 전용시설에서 직접 교육기부 프로그램 운영, 외부 위탁 근거 없음. 페이지 본문에 협력기관 표기 없음. 개인정보처리방침 위탁사도 에스텍(방문자 정보)·카카오엔터프라이즈(전산)뿐으로 교육 위탁사 없음.`,
