    kmaAngle: `**교사 연수(교수 연수) 프로그램 운영·콘텐츠 위탁**이 진입 각도. "2010년 교수 연수로 시작해 현재 교사·학생 대상으로 확대"라는 문구가 근거. 홍보팀 직접 접촉. **단 사회공헌활동백서 PDF(2018~2025 공개) 확보가 선행 과제** — 협력기관 실명이 여기 있을 가능성이 높음.`,
