  "한화": {
    updated: `2026-09-04`,
    programs: [
      `우주의 조약돌 — 중학생 6개월 과정. **주관이 KAIST 항공우주공학과**(교수진·석박사 멘토가 직접 운영). 주최 Hanwha Space Hub·한화에어로스페이스·한화시스템·㈜한화, 후원 우주항공청·한국과학창의재단`,
      `맑은학교 만들기 — **주최가 환경재단이고 한화는 후원**. 2026년 6개교 선정 완료. 학교별 맞춤 교육지도안 제공·시범 환경교육`,
      `한화 사이언스 챌린지 — 고교생 과학경진. 주최/주관 한화 자체, 후원 교육부·과기정통부·한국과학창의재단·유네스코`,
      `한화오션 오션넥스트업 진로교육 — 거제 19개 중학교. 2025년 9개교 282명 → 2026년 8개교 292명`,
      `한화토탈에너지스 에코더하기 환경교실 — 초록우산과 공동`,
      `한화 청소년오케스트라(충청, 2014~), 드림플러스(청년 창·취업)`,
      `해피선샤인 캠페인 (2011~2020 종료, 맑은학교로 승계)`,
    ],
    structure: `【한화 그룹 공통】 **⚠️ 한화문화재단은 교육과 완전히 무관.** 재단 사업이 퐁피두센터 한화 / 스페이스 제로원(뉴욕) / 영민 해외 레지던시 3개뿐이고 전부 순수 미술. 그룹 사회공헌 페이지에도 "문화예술 - 퐁피두 파트너십" 한 줄로만 등장. **그룹 통합 재단 없이 계열사·사업 단위로 각각 다른 외부 기관과 직접 협력**하는 분산형. 공식 문구: "2002년부터 계열사별로 사회공헌 전담조직과 전담인력을 배치". 사업별 실제 집행 주체: 우주의 조약돌=KAIST, 맑은학교=환경재단, 에코더하기=초록우산, 한화오션 진로교육=거제시교육지원청·거제시진로교육지원센터(교육부 진로플랫폼 "꿈길"로 접수, 멘토는 임직원 직접).`,
    contact: `**맑은학교 추진단 02-2011-4339 / 4316 (환경재단 소속)** — 한화 교육 예산의 실제 집행 창구 · Space Hub 문의 spacehub@hanwha.com · 한화 사이언스 챌린지 https://www.sciencechallenge.or.kr/ · 공개 입찰·공모 창구는 확인 못 함`,
    kmaAngle: `① **환경재단 경유가 유일하게 확인된 외주 경로.** 맑은학교가 "학교별 맞춤형 교육지도안 제공, 시범 환경교육 진행"을 명시하고 주최기관이 환경재단이므로 교육 콘텐츠·강사 파트의 창구는 환경재단 추진단(02-2011-4339). ② 한화오션 거제 진로교육이 확대 중이고 교사들이 지속운영을 요구 — 현재는 임직원 멘토 방식이나 확대 시 외부 운영 수요 가능. ③ **한화문화재단에 제안하지 말 것.** 미술 전담이라 교육 제안이 전달되지 않음.`,
    sources: [
      `https://www.hanwha.co.kr/sustainability/social/socialcontribution/activity.do?id=wrap-1`,
      `https://www.hanwhaspacehub.com/space-kids/introduce/`,
      `https://sunnyschool.co.kr/`,
      `https://m.hanwhafoundation.org/about/about`,
      `https://www.saegeoje.com/news/articleView.html?idxno=305802`,
    ],
    unknown: [
      `한화 각 사 개인정보처리방침 위탁 항목 — 그룹 사이트가 JS 렌더링이라 미도달`,
      `한화솔루션 "내일을 키우는 에너지교실"(190여개 학교, 13,500여명) 운영사 미확인`,
      `한화토탈에너지스의 2026년 현재 교육사업 운영사`,
    ],
  },

  "한화건설": {
    updated: `2026-09-04`,
    programs: [
      `우주의 조약돌 — 중학생 6개월 과정. **주관이 KAIST 항공우주공학과**(교수진·석박사 멘토가 직접 운영). 주최 Hanwha Space Hub·한화에어로스페이스·한화시스템·㈜한화, 후원 우주항공청·한국과학창의재단`,
      `맑은학교 만들기 — **주최가 환경재단이고 한화는 후원**. 2026년 6개교 선정 완료. 학교별 맞춤 교육지도안 제공·시범 환경교육`,
      `한화 사이언스 챌린지 — 고교생 과학경진. 주최/주관 한화 자체, 후원 교육부·과기정통부·한국과학창의재단·유네스코`,
      `한화오션 오션넥스트업 진로교육 — 거제 19개 중학교. 2025년 9개교 282명 → 2026년 8개교 292명`,
      `한화토탈에너지스 에코더하기 환경교실 — 초록우산과 공동`,
      `한화 청소년오케스트라(충청, 2014~), 드림플러스(청년 창·취업)`,
      `해피선샤인 캠페인 (2011~2020 종료, 맑은학교로 승계)`,
    ],
    structure: `【한화 그룹 공통】 **⚠️ 한화문화재단은 교육과 완전히 무관.** 재단 사업이 퐁피두센터 한화 / 스페이스 제로원(뉴욕) / 영민 해외 레지던시 3개뿐이고 전부 순수 미술. 그룹 사회공헌 페이지에도 "문화예술 - 퐁피두 파트너십" 한 줄로만 등장. **그룹 통합 재단 없이 계열사·사업 단위로 각각 다른 외부 기관과 직접 협력**하는 분산형. 공식 문구: "2002년부터 계열사별로 사회공헌 전담조직과 전담인력을 배치". 사업별 실제 집행 주체: 우주의 조약돌=KAIST, 맑은학교=환경재단, 에코더하기=초록우산, 한화오션 진로교육=거제시교육지원청·거제시진로교육지원센터(교육부 진로플랫폼 "꿈길"로 접수, 멘토는 임직원 직접).`,
    contact: `**맑은학교 추진단 02-2011-4339 / 4316 (환경재단 소속)** — 한화 교육 예산의 실제 집행 창구 · Space Hub 문의 spacehub@hanwha.com · 한화 사이언스 챌린지 https://www.sciencechallenge.or.kr/ · 공개 입찰·공모 창구는 확인 못 함`,
    kmaAngle: `① **환경재단 경유가 유일하게 확인된 외주 경로.** 맑은학교가 "학교별 맞춤형 교육지도안 제공, 시범 환경교육 진행"을 명시하고 주최기관이 환경재단이므로 교육 콘텐츠·강사 파트의 창구는 환경재단 추진단(02-2011-4339). ② 한화오션 거제 진로교육이 확대 중이고 교사들이 지속운영을 요구 — 현재는 임직원 멘토 방식이나 확대 시 외부 운영 수요 가능. ③ **한화문화재단에 제안하지 말 것.** 미술 전담이라 교육 제안이 전달되지 않음.`,
    sources: [
      `https://www.hanwha.co.kr/sustainability/social/socialcontribution/activity.do?id=wrap-1`,
      `https://www.hanwhaspacehub.com/space-kids/introduce/`,
      `https://sunnyschool.co.kr/`,
      `https://m.hanwhafoundation.org/about/about`,
      `https://www.saegeoje.com/news/articleView.html?idxno=305802`,
    ],
    unknown: [
      `한화 각 사 개인정보처리방침 위탁 항목 — 그룹 사이트가 JS 렌더링이라 미도달`,
      `한화솔루션 "내일을 키우는 에너지교실"(190여개 학교, 13,500여명) 운영사 미확인`,
      `한화토탈에너지스의 2026년 현재 교육사업 운영사`,
    ],
  },

